import { test, expect } from '@playwright/test';

test.describe('File Upload Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload'); // Replace with the actual URL of the upload page
  });

  test('should reject files larger than 5MB', async ({ page }) => {
    const fileInput = page.getByLabel('Upload File'); // Replace with the actual label of the file input
    const largeFilePath = 'path/to/large/file.txt'; // Replace with the actual path to a file larger than 5MB

    await fileInput.setInputFiles(largeFilePath);
    await page.getByRole('button', { name: 'Submit' }).click(); // Replace with the actual button role and name

    const errorMessage = await page.getByText('File size exceeds 5MB limit'); // Replace with the actual error message
    await expect(errorMessage).toBeVisible();
  });

  test('should accept files smaller than or equal to 5MB', async ({ page }) => {
    const fileInput = page.getByLabel('Upload File'); // Replace with the actual label of the file input
    const smallFilePath = 'path/to/small/file.txt'; // Replace with the actual path to a file smaller than or equal to 5MB

    await fileInput.setInputFiles(smallFilePath);
    await page.getByRole('button', { name: 'Submit' }).click(); // Replace with the actual button role and name

    const successMessage = await page.getByText('File uploaded successfully'); // Replace with the actual success message
    await expect(successMessage).toBeVisible();
  });
});
